function z(i,u,k,y){const n=3*i,s=3*(k-i)-n,a=1-n-s,c=3*u,f=3*(y-u)-c,b=1-c-f;return function(e,l=1e-6){if(e<=0)return 0;if(e>=1)return 1;let t=e;for(let r=0;r<8;r++){const o=((a*t+s)*t+n)*t-e;if(Math.abs(o)<l)return((b*t+f)*t+c)*t;const d=(3*a*t+2*s)*t+n;if(Math.abs(d)<1e-6)break;t-=o/d}let h=0,M=1;t=e;for(let r=0;r<20;r++){const o=((a*t+s)*t+n)*t;if(Math.abs(o-e)<l)break;e>o?h=t:M=t,t=(h+M)*.5}return((b*t+f)*t+c)*t}}export{z as default};
